class Solution { private int solve(int[] slices,int start,int end,int picks){int length=end-start+1,negative=-1_000_000_000;int[][] dp=new int[length+1][picks+1];for(int[] row:dp)Arrays.fill(row,negative);for(int i=0;i<=length;i++)dp[i][0]=0;for(int i=1;i<=length;i++)for(int chosen=1;chosen<=picks;chosen++){dp[i][chosen]=dp[i-1][chosen];int previous=dp[Math.max(0,i-2)][chosen-1];if(previous!=negative)dp[i][chosen]=Math.max(dp[i][chosen],previous+slices[start+i-1]);}return dp[length][picks];}public int maxSizeSlices(int[] slices){int picks=slices.length/3;return Math.max(solve(slices,0,slices.length-2,picks),solve(slices,1,slices.length-1,picks));} }
